UPDATE transfers SET from_club_id = (SELECT id FROM entities WHERE entity_type = 'club' AND canonical_name = 'Sint-Truiden' AND scope = 'Belgium') WHERE player_id = 740 AND transfer_date = '2020-04-01' AND from_club_id IS NULL;
UPDATE transfers SET from_club_id = (SELECT id FROM entities WHERE entity_type = 'club' AND canonical_name = 'Audax' AND scope = 'Brazil') WHERE player_id = 822 AND transfer_date = '2018-03-01' AND from_club_id IS NULL;

-- PART 4: older rows whose club ids were already filled in but whose text still said otherwise.
UPDATE transfers SET display_value = TRIM(SUBSTR(display_value, 1, INSTR(display_value, ' [') - 1)) WHERE id IN (28, 29, 32, 33, 39, 49, 50, 69, 72, 73, 82) AND INSTR(display_value, ' [') > 0 AND from_club_id IS NOT NULL AND to_club_id IS NOT NULL;
